// Compute date window for the past 7 days
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const since = sevenDaysAgo.toISOString();
const until = now.toISOString();

const periodStart = sevenDaysAgo.toISOString().split('T')[0];
const periodEnd = now.toISOString().split('T')[0];

const repoOwner = $env.REPO_OWNER || 'owner';
const repoName = $env.REPO_NAME || 'repo';
const githubToken = $env.GITHUB_TOKEN || '';
const anthropicKey = $env.ANTHROPIC_API_KEY || '';
const discordWebhook = $env.DISCORD_WEBHOOK || '';
const slackWebhook = $env.SLACK_WEBHOOK || '';
const emailTo = $env.EMAIL_TO || '';
const language = $env.SUMMARY_LANGUAGE || 'EN';

return [{
  json: {
    since, until, periodStart, periodEnd,
    repoOwner, repoName, githubToken,
    anthropicKey, discordWebhook, slackWebhook, emailTo, language
  }
}];

// Sanitize and normalize data from 3 parallel GitHub API calls
const sinceIso = $input.all()[0].json.since;

const rawCommits = $input.all()[0].json.body || [];
const rawIssues = $input.all()[1].json.body || [];
const rawPRs = $input.all()[2].json.body || [];

const commits = Array.isArray(rawCommits) ? rawCommits : [];
const issues = Array.isArray(rawIssues) ? rawIssues : [];
const allPRs = Array.isArray(rawPRs) ? rawPRs : [];

// Filter merged PRs within the week
const mergedPRs = allPRs.filter(p => p.merged_at && p.merged_at >= sinceIso);

// Filter issues closed this week (exclude PRs — they have pull_request key)
const closedIssues = issues.filter(i => {
  if (i.pull_request) return false;
  return i.closed_at && i.closed_at >= sinceIso;
});

// Extract author stats from commits
const authorMap = {};
commits.forEach(c => {
  const name = (c.commit?.author?.name) || (c.author?.login) || 'unknown';
  const login = c.author?.login || name;
  if (!authorMap[login]) authorMap[login] = { name, login, commits: 0, additions: 0, deletions: 0 };
  authorMap[login].commits++;
});

// Top 10 contributors
const topAuthors = Object.values(authorMap)
  .sort((a, b) => b.commits - a.commits)
  .slice(0, 10);

// Extract PR details for Claude
const prDetails = mergedPRs.slice(0, 15).map(p => ({
  number: p.number,
  title: p.title,
  author: p.user?.login || 'unknown',
  merged_at: p.merged_at
}));

// Extract issue details
const issueDetails = closedIssues.slice(0, 15).map(i => ({
  number: i.number,
  title: i.title,
  author: i.user?.login || 'unknown',
  closed_at: i.closed_at,
  labels: (i.labels || []).map(l => l.name)
}));

const periodStart = $input.all()[0].json.periodStart;
const periodEnd = $input.all()[0].json.periodEnd;
const language = $input.all()[0].json.language || 'EN';

// Construct stats
const stats = {
  period: `${periodStart} → ${periodEnd}`,
  total_commits: commits.length,
  unique_authors: Object.keys(authorMap).length,
  closed_issues: closedIssues.length,
  merged_prs: mergedPRs.length,
  top_contributors: topAuthors,
  prs: prDetails,
  issues: issueDetails
};

return [{
  json: {
    ...$input.all()[0].json,
    stats,
    rawCommits: commits.slice(0, 30),
    rawPRs: mergedPRs.slice(0, 30),
    rawIssues: closedIssues.slice(0, 30)
  }
}];

// Build Claude API request body
const stats = $input.first().json.stats;
const language = $input.first().json.language || 'EN';

const isFrench = language.toUpperCase() === 'FR';

const systemPrompt = isFrench
  ? `Tu es un assistant qui résume l'activité hebdomadaire de développement d'un dépôt GitHub. Génère un résumé narratif concis, engageant et informatif en français. Structure : résumé global, contributeurs notables, PRs marquantes, issues résolues, tendances. Maximum 500 mots. Sois précis et factuel.`
  : `You are an assistant that summarizes weekly development activity for a GitHub repository. Generate a concise, engaging, informative narrative summary in English. Structure: overall summary, notable contributors, standout PRs, resolved issues, trends. Maximum 500 words. Be precise and factual.`;

const prList = stats.prs.map(p => `- #${p.number}: ${p.title} (${p.author})`).join('
');
const issueList = stats.issues.map(i => `- #${i.number}: ${i.title} (${i.author}) [${(i.labels || []).join(', ')}]`).join('
');
const contributorList = stats.top_contributors.map(c => `- ${c.login}: ${c.commits} commits`).join('
');

const userMessage = isFrench
  ? `Période : ${stats.period}

Statistiques :
- ${stats.total_commits} commits par ${stats.unique_authors} contributeurs
- ${stats.closed_issues} issues fermées
- ${stats.merged_prs} PRs mergées

Contributeurs :
${contributorList}

PRs mergées :
${prList || 'Aucune'}

Issues fermées :
${issueList || 'Aucune'}

Génère un résumé narratif de cette semaine.`
  : `Period: ${stats.period}

Statistics:
- ${stats.total_commits} commits by ${stats.unique_authors} contributors
- ${stats.closed_issues} issues closed
- ${stats.merged_prs} PRs merged

Contributors:
${contributorList}

Merged PRs:
${prList || 'None'}

Closed Issues:
${issueList || 'None'}

Generate a narrative summary of this week.`;

const claudeBody = {
  model: 'claude-sonnet-4-20250514',
  max_tokens: 1024,
  system: systemPrompt,
  messages: [
    { role: 'user', content: userMessage }
  ]
};

return [{
  json: {
    ...$input.first().json,
    claudeBody,
    systemPrompt,
    userMessage
  }
}];

// Parse Claude response and format output
const claudeResponse = $input.first().json.body || $input.first().json;
const narrative = claudeResponse.content?.[0]?.text || claudeResponse.error?.message || 'Summary generation failed';
const stats = $input.first().json.stats;
const period = stats.period;

const topContributorsFormatted = stats.top_contributors
  .map((c, i) => `${i + 1}. **${c.login}** — ${c.commits} commits`)
  .join('\n');

const topPRsFormatted = stats.prs
  .slice(0, 5)
  .map(p => `- **#${p.number}** ${p.title} (@${p.author})`)
  .join('\n');

const topIssuesFormatted = stats.issues
  .slice(0, 5)
  .map(i => `- **#${i.number}** ${i.title}`)
  .join('\n');

// Discord-compatible markdown (max 2000 chars per message for Discord)
const discordBody = `📊 **Weekly Dev Digest — ${period}**\n\n` +
  `🔄 **${stats.total_commits} commits** by **${stats.unique_authors}** contributors\n` +
  `🐛 **${stats.closed_issues} issues** closed\n` +
  `✅ **${stats.merged_prs} PRs** merged\n\n` +
  `**👥 Top Contributors**\n${topContributorsFormatted}\n\n` +
  `**🔀 Merged PRs**\n${topPRsFormatted}\n\n` +
  `**📝 Narrative**\n${narrative}`;

// Slack-compatible format
const slackBody = {
  blocks: [
    { type: 'header', text: { type: 'plain_text', text: `📊 Weekly Dev Digest — ${period}` } },
    { type: 'section', text: { type: 'mrkdwn', text: `🔄 *${stats.total_commits} commits* by *${stats.unique_authors}* contributors\n🐛 *${stats.closed_issues} issues* closed\n✅ *${stats.merged_prs} PRs* merged` } },
    { type: 'section', text: { type: 'mrkdwn', text: `*👥 Top Contributors*\n${topContributorsFormatted}` } },
    { type: 'section', text: { type: 'mrkdwn', text: `*🔀 Merged PRs*\n${topPRsFormatted}` } },
    { type: 'section', text: { type: 'mrkdwn', text: `*📝 Narrative*\n${narrative.substring(0, 2500)}` } }
  ]
};

// Plain text for email
const emailBody = `Weekly Dev Digest — ${period}\n\n` +
  `Activity:\n` +
  `  ${stats.total_commits} commits by ${stats.unique_authors} contributors\n` +
  `  ${stats.closed_issues} issues closed\n` +
  `  ${stats.merged_prs} PRs merged\n\n` +
  `Top Contributors:\n${topContributorsFormatted}\n\n` +
  `Merged PRs:\n${topPRsFormatted}\n\n` +
  `Narrative:\n${narrative}`;

return [{
  json: {
    ...$input.first().json,
    discordBody: discordBody.substring(0, 1900),
    slackBody: JSON.stringify(slackBody),
    emailBody,
    narrative,
    summaryText: narrative
  }
}];

// Log summary to console for debugging
const stats = $input.first().json.stats;
const narrative = ($input.first().json.narrative || '').substring(0, 100);

console.log('=== Weekly Dev Digest Complete ===');
console.log(`Period: ${stats.period}`);
console.log(`Commits: ${stats.total_commits} | Issues: ${stats.closed_issues} | PRs: ${stats.merged_prs}`);
console.log(`Authors: ${stats.unique_authors}`);
console.log(`Narrative preview: ${narrative}...`);

return $input.all();
